async def extract(page) -> dict:
    """The page as a user sees it: visible text of the page and its frames, image labels, links."""
    data = await page.main_frame.evaluate(EXTRACT_JS)
    for frame in page.frames[1:]:
        try:
            sub = await asyncio.wait_for(frame.evaluate(EXTRACT_JS), 5)
        except Exception:
            continue
        if sub.get("text", "").strip():
            data["text"] += f"\n[frame {sub['url']}]\n" + sub["text"]
            data["images"] += sub["images"]
            data["links"] += sub["links"]
            data["password"] = data["password"] or sub["password"]
    return data


async def render(site: str, url: str) -> dict:
    """Open `url` in a background tab of the site's browser context (shares the login), read it, close the tab."""
    sem = _sem.setdefault(site, asyncio.Semaphore(PARALLEL))
    async with sem:
        context = (await site_page(site)).context
        page = await context.new_page()
        try:
            status = None
            for attempt in range(3):
                try:
                    response = await page.goto(url, wait_until="commit", timeout=NAV_TIMEOUT_MS)
                    status = response.status if response else None
                except Exception as error:  # noqa: BLE001
                    if attempt == 2:
                        return {"url": url, "error": str(error).splitlines()[0][:200]}
                    await asyncio.sleep(1 + attempt)
                    continue
                try:
                    await page.wait_for_load_state("domcontentloaded", timeout=8000)
                except Exception:  # noqa: BLE001 - a page that never finishes loading is still read
                    pass
                await page.wait_for_timeout(600)
                if status in (429, 502, 503, 504) and attempt < 2:
                    await asyncio.sleep(1.5 * (attempt + 1))
                    continue
                break
            data = await extract(page)
            data["status"] = status
            visited[site].add(clean_url(url))
            return data
        finally:
            await page.close()


def compact(site: str, data: dict, offset: int = 0, links: bool = False) -> str:
    """The text for the model: zero-width characters gone, marked numbers plain, the site's navigation chrome
    (short lines without digits seen on 3+ pages) dropped after it was shown, at most PAGE_CHARS characters."""
    url = clean_url(data.get("url", ""))
    lines = []
    for line in normalize(data.get("text", "").translate(ZERO_WIDTH)).splitlines():
        line = re.sub(r"[ \t]+", " ", line.replace("\t", " | ")).strip()
        if not line:
            continue
        if len(line) < 60 and not re.search(r"\d", line):
            if (line, url) not in boiler_seen[site]:
                boiler_seen[site].add((line, url))
                boiler[site][line] += 1
            if boiler[site][line] > 3:
                continue
        lines.append(line)
    text = "\n".join(lines)
    if data.get("images"):
        text += "\n[images: " + " | ".join(normalize(i.translate(ZERO_WIDTH)) for i in data["images"]) + "]"
    if data.get("password"):
        text = "[this page has a password field: a login page, or the session expired]\n" + text
    more = ""
    if len(text) > offset + PAGE_CHARS:
        more = f"\n[... {len(text) - offset - PAGE_CHARS} more characters: read again with offset={offset + PAGE_CHARS}]"
    text = text[offset:offset + PAGE_CHARS] + more
    if links:
        base = SITES.get(site, "")
        seen, rows = set(), []
        for l in data.get("links", []):
            href = clean_url(l["href"])
            if site_of(href) != site or href in seen or not l["text"]:
                continue
            seen.add(href)
            rows.append(f"{l['text'][:60]} -> {href[len(base):] if base and href.startswith(base) else href}")
        text += "\n[links]\n" + "\n".join(rows[:80])
    return f"## {url}\n{text}"


def guard(seconds: float):
    def wrap(fn):
        @functools.wraps(fn)
        async def inner(*args, **kwargs):
            try:
                return await asyncio.wait_for(fn(*args, **kwargs), seconds)
            except asyncio.TimeoutError:
                return f"FAILED: no result within {seconds:.0f} s"
            except LookupError as error:
                return f"FAILED: {error}"
            except Exception as error:  # noqa: BLE001 - a tool answers, it never crashes the session
                return f"FAILED: {type(error).__name__}: {str(error).splitlines()[0][:200] if str(error) else ''}"
        return inner
    return wrap


@server.tool()
@guard(30)
async def read(site: str, url: str = "", offset: int = 0, links: bool = False) -> str:
    """Read a page as text, the way a user sees it: visible text of the page and its frames, image labels,
    numbers that carry a format marker such as "1,234.5 (en-US)" already converted to plain numbers. Much cheaper
    than a browser snapshot when you need the content of a page rather than its controls.
    - url empty: the page currently shown in that site's tab (after you clicked there).
    - url given: that page, opened in a background tab of the same login (a page you saw a link to). Never use it for
      forms, searches that need a button, or anything that saves, confirms or sends.
    - links=true also lists the page's links (text -> address). offset reads on in a long page."""
    if url:
        url = clean_url(urljoin(SITES.get(site, "") + "/", url))
        data = await render(site, url)
        if data.get("error"):
            return f"FAILED: {data['error']} - open it by clicking instead"
    else:
        page = await site_page(site)
        data = await extract(page)
    return compact(site, data, offset, links)


@server.tool()
@guard(90)
async def fetch_like(site: str, example_url: str, example_value: str, values: list[str]) -> str:
    """Read many pages of the same kind at once, after you reached ONE of them by clicking. Give that page's address
    (example_url), the value in it that identifies the record or page (example_value, e.g. a key or a page number
    that appears in the address), and the other values you want (values, at most 20). Each page is opened in a
    background tab of the same login and returned as text. Much faster than clicking to each one.
    A page that cannot be read this way comes back as "FAILED: <reason> - open it by clicking": then click to it
    instead, don't retry the same address. Only for reading; never for forms, gates, or actions."""
    example = clean_url(urljoin(SITES.get(site, "") + "/", example_url))
    await browser()
    known = visited[site] | {clean_url(p.url) for c in _browser.contexts for p in c.pages}
    if example not in known:
        return ("FAILED: reach one page of this kind by clicking first (or read it), then call fetch_like with its "
                "exact address")
    token = next((t for t in (example_value, quote(example_value, safe=""), quote(example_value)) if t in example),
                 None)
    if not token:
        return f"FAILED: {example_value!r} does not appear in {example}"
    if example.count(token) != 1:
        return f"FAILED: {example_value!r} appears {example.count(token)} times in the address: ambiguous"
    values = [str(v) for v in values][:20]
    urls = [example.replace(token, quote(v, safe="") if token != example_value else v) for v in values]
    reference, *results = await asyncio.gather(render(site, example), *(render(site, u) for u in urls))
    ref_len = len(reference.get("text") or "")
    ref_path = urlparse(example).path
    out = []
    for value, url, data in zip(values, urls, results):
        text = data.get("text") or ""
        reason = None
        if data.get("error"):
            reason = data["error"]
        elif data.get("status") and data["status"] >= 400:
            reason = f"HTTP {data['status']}"
        elif data.get("password"):
            reason = "a login page (session expired?)"
        elif urlparse(clean_url(data.get("url", ""))).path != urlparse(url).path and ref_path == urlparse(url).path:
            reason = f"redirected to {data.get('url')}"
        elif not re.search(r"(?<![\w-])" + re.escape(unquote(value)) + r"(?![\w-])", text.translate(ZERO_WIDTH), re.I):
            reason = f"the page does not show {value!r}"
        elif ref_len and len(text) < 0.4 * ref_len:
            reason = "much shorter than the example page"
        if reason:
            out.append(f"## {value}: FAILED: {reason} - open it by clicking")
        else:
            out.append(compact(site, data))
    return "\n\n".join(out)


